#include <iostream>
#include <vector>
#include <string>
#include <sstream>

using namespace std;

struct Point {
    vector<long> coords;

    Point(const vector<long>& c) : coords(c) {}

    long computeSquaredLength() const {
        long total = 0;
        for (long c : coords) {
            total += c * c;
        }
        return total;
    }

    long innerProduct(const Point& other) const {
        long sum = 0;
        for (size_t i = 0; i < coords.size(); i++) {
            sum += coords[i] * other.coords[i];
        }
        return sum;
    }

    Point subtract(const Point& other) const {
        vector<long> newCoords(coords.size());
        for (size_t i = 0; i < coords.size(); i++) {
            newCoords[i] = coords[i] - other.coords[i];
        }
        return Point(newCoords);
    }
};

bool validatePoint(const vector<Point>& pts, int index) {
    const Point& p = pts[index];
    int total = pts.size();
    for (int j = 0; j < total; j++) {
        if (j == index) continue;
        for (int k = 0; k < total; k++) {
            if (k == index || k == j) continue;
            Point v1 = pts[j].subtract(p);
            Point v2 = pts[k].subtract(p);
            if (v1.innerProduct(v2) > 0) return false;
        }
    }
    return true;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    if (n > 11) {
        cout << 0 << "\n";
        return 0;
    }
    vector<Point> points;
    for (int i = 0; i < n; i++) {
        string line;
        getline(cin, line);
        // To handle the case where getline consumes leftover newline
        if (line.empty()) {
            getline(cin, line);
        }
        stringstream ss(line);
        vector<long> coords(5);
        for (int j = 0; j < 5; j++) {
            ss >> coords[j];
        }
        points.emplace_back(coords);
    }
    vector<int> validIndices;
    for (int i = 0; i < n; i++) {
        if (validatePoint(points, i)) {
            validIndices.push_back(i + 1);
        }
    }
    cout << validIndices.size() << "\n";
    for (int idx : validIndices) {
        cout << idx << "\n";
    }
    return 0;
}

